start.tests/adapter.py:
"""Maps scenario commands onto the engine API (the scenario runner is tests/test_scenarios.py)."""
import lanternfall


class Adapter:
    def __init__(self):
        self.game = None

    def run(self, verb, args):
        if verb == "new":                     # new <world text, "\\n" escapes expanded>
            self.game = lanternfall.Game(args.replace("\\n", "\n"))
            return "ok"
        if verb == "say":                     # say <command line>: the reply text
            return self.game.step(args)
        if verb == "status":                  # "<score> <steps> <finished>"
            g = self.game
            return "%d %d %s" % (g.score(), g.steps(), "yes" if g.finished() else "no")
        raise KeyError(verb)

start.tests/test_scenarios.py:
"""Replays every scenario file in tests/data/ against the engine through tests/adapter.py.

A scenario file has `# scenario <name>` headers, each followed by pairs of lines: `> verb args` (a command for the
adapter) and `= text` (the exact reply; a newline inside a reply is written \n and a backslash \\)."""
import glob
import os
import unittest

from adapter import Adapter

DATA = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data")


def esc(s):
    return str(s).replace("\\", "\\\\").replace("\n", "\\n")


def load_scenarios(path):
    out, pending = [], None
    with open(path, encoding="utf-8") as f:
        for raw in f.read().split("\n"):
            if raw.startswith("# scenario"):
                out.append((raw[len("# scenario"):].strip(), []))
            elif raw.startswith("> "):
                pending = raw[2:]
            elif raw.startswith("=") and pending is not None and out:
                out[-1][1].append((pending, raw[2:]))
                pending = None
    return out


class ScenarioTest(unittest.TestCase):
    def test_scenarios(self):
        files = sorted(glob.glob(os.path.join(DATA, "*.txt")))
        self.assertTrue(files, "no scenario files in tests/data")
        for path in files:
            for name, steps in load_scenarios(path):
                with self.subTest(file=os.path.basename(path), scenario=name):
                    adapter = Adapter()
                    for i, (cmd, want) in enumerate(steps, 1):
                        verb, _, args = cmd.partition(" ")
                        got = esc(adapter.run(verb, args))
                        if got != want:
                            self.fail("step %d: > %s\n  expected: %s\n  got:      %s" % (i, cmd, want, got))


if __name__ == "__main__":
    unittest.main()

